def backfill_cards() -> None:
    """Price the cards made before the ledger existed, from the usage stored on each message.
    (Titles and Surprise me picks from that period weren't stored; they cost well under a cent.)"""
    import json

    from app.llm.pricing import cost_usd

    conn = op.get_bind()
    rows = conn.execute(sa.text(
        "select m.thread_id, t.user_id, m.model, m.usage, m.created_at from message m "
        "join thread t on t.id = m.thread_id where m.role = 'assistant' and m.usage is not null"
    )).all()
    for thread_id, user_id, model, usage, created_at in rows:
        created = usage.get("cache_creation") or {}
        conn.execute(
            sa.text(
                "insert into api_call (user_id, purpose, model, thread_id, input_tokens, cache_write_tokens, "
                "cache_read_tokens, output_tokens, cost_usd, usage, ts) values (:u, 'turn', :m, :t, :i, :w, :r, :o, "
                ":c, cast(:usage as jsonb), :ts)"
            ),
            {
                "u": user_id, "m": model or "claude-opus-5-5", "t": thread_id,
                "i": usage.get("input_tokens", 0),
                "w": sum(created.values()) if created else usage.get("cache_creation_input_tokens", 0),
                "r": usage.get("cache_read_input_tokens", 0), "o": usage.get("output_tokens", 0),
                "c": round(cost_usd(model or "claude-opus-5-5", usage), 6), "usage": json.dumps(usage), "ts": created_at,
            },
        )


